import json
p='/workspace/stage/getfasta_form.json'
d=json.load(open(p))
print(json.dumps(d.get('state_inputs'),indent=2)[:4000])
# find option value containing hg38
def walk(x):
    if isinstance(x,dict):
        if x.get('name')=='fasta_id':
            opts=x.get('options',[])
            for o in opts:
                if 'hg38' in str(o):
                    print('MATCH',o)
        for v in x.values(): walk(v)
    elif isinstance(x,list):
        for v in x: walk(v)
walk(d)
